-- fetchOne

@Test
void fetchOne() {
    em.clear();
    Member m = queryFactory.selectFrom(member)
            .where(member.username.eq("m1")).fetchOne();
    System.out.println("이름: " + m.getUsername());

    em.clear();
    Member none = queryFactory.selectFrom(member)
            .where(member.username.eq("없음")).fetchOne();
    System.out.println("없을 때: " + none);
}

