-- 두 건이면 터진다

@Test
void fetchOne_두_건() {
    em.clear();
    try {
        queryFactory.selectFrom(member)
                .where(member.age.eq(10)).fetchOne();
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
        System.out.println("말:   " + e.getMessage());
    }
}

