@Test
void fetchFirst() {
    em.clear();
    Member m = queryFactory.selectFrom(member)
            .where(member.age.eq(10))
            .orderBy(member.username.asc())
            .fetchFirst();
    System.out.println("이름: " + m.getUsername());
}

