-- group by 를 넣으면 틀린다

@Test
void fetchResults_group_by() {
    em.clear();
    QueryResults<Integer> results = queryFactory
            .select(member.age)
            .from(member)
            .groupBy(member.age)
            .fetchResults();

    System.out.println("getTotal():   " + results.getTotal());
    System.out.println("실제 행 수:   " + results.getResults().size());
}

