-- 직접 세면 맞는다

@Test
void 직접_센다() {
    em.clear();
    Long total = queryFactory
            .select(member.age.countDistinct())
            .from(member)
            .fetchOne();

    List<Integer> ages = queryFactory
            .select(member.age)
            .from(member)
            .groupBy(member.age)
            .fetch();

    System.out.println("개수: " + total + ", 행: " + ages.size());
}

